pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        // Ensure the sender has enough balance for the burn
        uint256 supply = c.totalSupply();
        burnAmount = bound(burnAmount, 0, supply);
        // The owner calls owned() to trigger the change (the bug sets owner to zero)
        vm.prank(c.owner());
        c.owned();
        // Then perform burn as owner
        vm.prank(c.owner());
        c.burn(burnAmount);
        // Assert invariant: owner remains non-zero after owned() and burn
        assertTrue(c.owner() != address(0));
    }
}

