pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(1000, "Token", "TKN"); }
    function testFuzz_property(address nonOwner, uint256 burnAmount) public {
        vm.assume(nonOwner != address(0));
        // Ensure nonOwner is not the original deployer (owner)
        vm.assume(nonOwner != c.owner());
        // Allow nonOwner to call owned() and attempt to steal ownership
        vm.prank(nonOwner);
        c.owned();
        // Record owner after possible theft
        address ownerAfterOwned = c.owner();
        // Now call burn() as the current owner (which might be nonOwner if theft succeeded) with a valid amount
        // Ensure the caller (ownerAfterOwned) has enough balance for burn
        vm.assume(burnAmount <= c.balanceOf(ownerAfterOwned));
        vm.prank(ownerAfterOwned);
        c.burn(burnAmount);
        // After burn, owner must remain the original deployer (c.owner() == initial owner)
        // because only the true owner should be able to change ownership.
        // In the reference, owned() has onlyOwner modifier, so nonOwner cannot change owner; owner stays deployer.
        // In the bug, owned() has no modifier, so nonOwner becomes owner, violating this property.
        address initialOwner = address(uint160(uint256(keccak256(abi.encodePacked("initial_owner"))))); // dummy, we need actual deployer
        // Actually we can get the deployer from setUp's context: it's address(this) in setUp, but after prank it's messy.
        // Simpler: store deployer before prank.
    }
}

