pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 amount, address target, bool freeze) public {
        // 1. Admissible domain: keep it wide, just ensure burn amount is > 0 and target is not owner
        bound(amount, 1, type(uint256).max);
        vm.assume(target != address(this));

        // 2. Setup: mint tokens to owner so burn has something to burn
        vm.prank(address(this));
        c.mintToken(address(this), amount);

        // 3. Attempt burn through the public entry point
        bool ok;
        try c.burn(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // 4. Assert: if burn succeeded (ok == true), owner must be set to the deployer (address(this)).
        // In buggy version, burn reverts (ok == false) so owner stays zero, violating the rule that any successful burn implies owner is set.
        assertTrue(!ok || c.owner() == address(this));
    }
}

